#!/usr/bin/env python3
"""Figure 1: the pair of closed forms generated by an affine local scale a = a_p + xi (E - E_p), under the condensation approximation."""
import numpy as np
from style import *
fig, (a, b) = plt.subplots(1, 2, figsize=(7.0, 2.9))
u = np.linspace(-1.2, 4.0, 600)
cases = [(-1.0, "ξ = −1 (Temkin)"), (-0.5, "ξ = −1/2"), (0.0, "ξ = 0 (Freundlich)"), (0.5, "ξ = +1/2 (Halsey type)")]
for (xi, lab), col in zip(cases, C):
    with np.errstate(invalid="ignore", divide="ignore"):
        y = np.exp(-u) if xi == 0 else np.where(1 + xi*u > 0, np.abs(1 + xi*u)**(-1/xi), np.nan)
    a.plot(u, y, color=col, label=lab)
a.set_yscale("log"); a.set_ylim(1e-2, 6); a.set_xlim(-1.2, 4.0)
for xi, col in ((-1.0, C[0]), (-0.5, C[1])): a.plot([-1/xi], [1.25e-2], "v", ms=5, mfc="white", mec=col, mew=1.2, zorder=5)
a.set_xlabel(r"$u=(RT/a_p)\,\ln(z_p/z)$"); a.set_ylabel(r"$\theta/\theta_p$"); a.legend(frameon=False, loc="upper right"); panel(a, "a")
r = np.logspace(-2.5, 0.6, 400)                       # theta/theta_p
for (xi, lab), col in zip(cases, C):
    q = -np.log(r) if xi == 0 else (r**(-xi) - 1)/xi
    b.plot(r, q, color=col, label=lab)
    if xi < 0: b.plot([r[0]], [-1/xi], "*", ms=8, color=col, clip_on=False, zorder=5)
b.set_xscale("log"); b.set_xlim(r[0], r[-1]); b.set_ylim(-1.5, 6)
b.set_xlabel(r"$\theta/\theta_p$"); b.set_ylabel(r"$[Q_{\rm st}(\theta)-Q_{\rm st}(\theta_p)]/a_p$"); panel(b, "b")
fig.tight_layout(); fig.savefig("fig_pair.pdf"); fig.savefig("fig_pair.png", dpi=200); print("ok")
